@Service
public class OrderService {
    // In a monolith, this would be a direct repository call.
    // In microservices, we use a Feign client or WebClient to call the Inventory service.
    private final InventoryClient inventoryClient;

    public void placeOrder(OrderRequest request) {
        // Circuit breaker prevents cascading failure if Inventory is down
        if (inventoryClient.checkStock(request.getItemId())) {
             orderRepository.save(request);
        } else {
             throw new OutOfStockException();
        }
    }
}
